import UIKit

enum MockLifecycleEvent {
    case didBecomeActive
    case willResignActive
    case didEnterBackground
}

func handle(event: MockLifecycleEvent) -> String {
    switch event {
    case .didBecomeActive:
        return "resume animations"
    case .willResignActive:
        return "pause game timer"
    case .didEnterBackground:
        return "persist state"
    }
}
print("Action: \(handle(event: .willResignActive))")

import SwiftUI

func checkPhase(_ phase: ScenePhase) -> String {
    if phase == .background {
        return "save to disk"
    } else {
        return "keep running"
    }
}
print("Action on background: \(checkPhase(.background))")

