import SwiftUI

struct SceneStatusChecker {
    static func isInteractive(phase: ScenePhase) -> Bool {
        return phase == .active
    }
}

let activeCheck = SceneStatusChecker.isInteractive(phase: .active)
let inactiveCheck = SceneStatusChecker.isInteractive(phase: .inactive)
print("Interactive check: \(activeCheck && !inactiveCheck)")

struct LifecycleCoordinator {
    var isSaved: Bool = false

    mutating func updateState(event: String) -> String {
        if event == "background" {
            isSaved = true
            return "saved"
        }
        return "running"
    }
}

var coordinator = LifecycleCoordinator()
let res = coordinator.updateState(event: "background")
print("Result: \(res), Saved: \(coordinator.isSaved)")

import UIKit

class MultiWindowManager {
    func countActiveScenes(states: [UIScene.ActivationState]) -> Int {
        return states.filter { $0 == .foregroundActive }.count
    }
}

let manager = MultiWindowManager()
let states: [UIScene.ActivationState] = [.foregroundActive, .foregroundInactive, .background, .foregroundActive]
print("Active count: \(manager.countActiveScenes(states: states))")
